// Public-portfolio audio placeholders.
//
// Every checked-in file under assets/Sound is generated by this script as a
// valid silent PCM WAV whose samples are all zero. No recorded speech, music
// sample, third-party audio, synthesized tone, or external generation service
// is used.
// Run `npm run assets:audio-placeholders` to regenerate the files.

import { mkdir, writeFile } from "node:fs/promises";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const soundRoot = join(root, "assets", "Sound");
const sampleRateHz = 22_050;

function createSilentWav(durationMs) {
  const sampleCount = Math.max(1, Math.round((durationMs / 1_000) * sampleRateHz));
  const bytesPerSample = 2;
  const dataSize = sampleCount * bytesPerSample;
  const wav = Buffer.alloc(44 + dataSize);

  wav.write("RIFF", 0, "ascii");
  wav.writeUInt32LE(36 + dataSize, 4);
  wav.write("WAVE", 8, "ascii");
  wav.write("fmt ", 12, "ascii");
  wav.writeUInt32LE(16, 16);
  wav.writeUInt16LE(1, 20);
  wav.writeUInt16LE(1, 22);
  wav.writeUInt32LE(sampleRateHz, 24);
  wav.writeUInt32LE(sampleRateHz * bytesPerSample, 28);
  wav.writeUInt16LE(bytesPerSample, 32);
  wav.writeUInt16LE(16, 34);
  wav.write("data", 36, "ascii");
  wav.writeUInt32LE(dataSize, 40);

  return wav;
}

const silentBgmPlaceholders = [
  ["BGM/placeholder-main-loop.wav", 2_000],
];

const silentSfxPlaceholders = [
  ["SFX/placeholder-charge-loop.wav", 800],
  ["SFX/placeholder-overcharge-loop.wav", 800],
  ["SFX/placeholder-cue-charge-start.wav", 180],
  ["SFX/placeholder-cue-stance.wav", 220],
  ["SFX/placeholder-cue-stance-overcharge.wav", 220],
  ["SFX/placeholder-cue-punch.wav", 180],
  ["SFX/placeholder-cue-punch-overcharge.wav", 180],
  ["SFX/placeholder-crack-01.wav", 120],
  ["SFX/placeholder-crack-02.wav", 120],
  ["SFX/result_sfx/Unique_SFX/placeholder-unique.wav", 260],
  ["SFX/result_sfx/Featured/placeholder-featured.wav", 320],
];

const silentResultPlaceholders = Array.from({ length: 10 }, (_, index) => [
  `SFX/result_sfx/placeholder-result-${String(index + 1).padStart(2, "0")}.wav`,
  150 + index * 6,
]);

const placeholders = [
  ...silentBgmPlaceholders,
  ...silentSfxPlaceholders,
  ...silentResultPlaceholders,
];

for (const [relativePath, durationMs] of placeholders) {
  const outputPath = join(soundRoot, relativePath);
  await mkdir(dirname(outputPath), { recursive: true });
  await writeFile(outputPath, createSilentWav(durationMs));
}

console.log(`generated ${placeholders.length} public placeholder audio files`);
